          </el-select>
        </el-form-item> -->
        <el-form-item label="大类类型" label-width="80px">
          <el-select v-model="queryParams.model_template_config_type_id" placeholder="请选择模型类型" size="small" clearable filterable style="width: 90%" @change="axioss()">
            <el-option v-for="item in modelTypeOptions" :key="'查询'+item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button icon="el-icon-search" type="primary" size="small" @click="axioss">搜索</el-button>
