        <el-form-item label="算法" prop="model_name">
          <el-input v-model="formData.model_name" autocomplete="off" placeholder="请输入算法"></el-input>
        </el-form-item>
        <!-- <el-form-item label="模型类型" prop="model_type">
          <el-select v-model="formData.model_type" placeholder="请选择模型类型" clearable filterable style="width: 100%" @change="axioss()">
            <el-option v-for="item in modelTypeDict" :key="item.data_value+item.data_label" :label="item.data_label" :value="item.data_value"> </el-option>
          </el-select>
        </el-form-item> -->
        <el-form-item label="大类类型" prop="model_template_config_type_id">
          <el-select v-model="formData.model_template_config_type_id" placeholder="请选择大类类型" clearable filterable style="width: 100%" @change="axioss()">
            <el-option v-for="item in modelTypeOptions" :key="item.id+item.model_type_name" :label="item.model_type_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <!-- <el-form-item label="自定义配置" prop="model_conf_list">
          <div style="width: 100%;margin-bottom: 5px;" v-for="(item,index) in modelListArr" :key="index+item">
            <el-input style="width: 75%;" v-model="item.value" autocomplete="off" placeholder="请输入内容"></el-input>
            &nbsp;&nbsp;
            <el-button icon="el-icon-plus" type="success" circle style="display: inline;" @click="handleAddList"></el-button>
            &nbsp;&nbsp;
            <el-button icon="el-icon-minus" type="danger" circle style="display: inline;" @click="handleDeleteList(index)" v-if="index!=0"></el-button>
          </div>
        </el-form-item> -->
      </el-form>

      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取 消</el-button>
        <el-button type="primary" @click="handleSubmit">确 定</el-button>
      </div>
