</template>
  
  <script>
import { modelApi } from '@/api/model';
import { dictApi } from '@/api/system/dict';

import { MessageBox } from 'element-ui'
export default {
  data() {
    return {
      // 表格相关数据
      tableData: [],
      queryParams: {
        page: 1,
        per_page: 15,
        model_type: '',//模型类型
        model_template_config_type_id:'',//大类类型
      },
      total: 0,
      pagesizes: [15, 35, 50, 100, 150, 200, 300],
      modelTypeOptions: [],//大类字典
      // modelTypeDict: [],//模型类型字典
      // 新增、修改相关数据
      dialogTitle: '',
      dialogVisible: false,
      formData: {
        model_name: '',
        model_type: '',
        model_template_config_type_id: '',
        model_conf_list: '',
      },
      modelListArr: [{ value: '' }],
      rules: {
        model_name: [
          { required: true, message: '请输入算法', trigger: 'blur' }
        ],
        model_type: [
          { required: true, message: '请选择模型类型', trigger: 'change' }
        ],
        model_template_config_type_id: [
          { required: true, message: '请选择大类类型', trigger: 'change' }
        ]
      },
      config: {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      }
    };
  },
  created() {
    this.getModelType();
  },
  mounted() {
    this.axioss();
  },
  methods: {
    // 页码变化
    handleCurrentChange(val) {
      this.queryParams.page = val;
      this.axioss();
    },
    // 当前页数据条数变化
    handleSizeChange(val) {
      this.queryParams.per_page = val;
      this.axioss();
    },
    // 查询表格数据
    axioss() {
      this.$http.get(modelApi.getModelList, {
        params: this.queryParams
      }).then(response => {
        this.tableData = response.data.data.data
        this.total = response.data.data.pagination.total_items
      }).catch(rek => {
        console.log(rek)
      })
    },
    // 查询，模型类型、大类
    getModelType() {
      // 大类
      this.$http.get(modelApi.getModelType, {
        params: {
          page: 1,
          per_page: 999
        }
      }).then(response => {
        this.modelTypeOptions = response.data.data.data
      }).catch(rek => {
        console.log(rek)
      })
      // 模型类型
      // this.$http.get(dictApi.getDictDataList, {
      //   params: {
      //     type_code: 4,
      //     page: 1,
      //     per_page: 999,
      //   }
      // }).then(res => {
      //   if (res.data.code == 200) {
      //     this.modelTypeDict = res.data.data_list.data
      //   }
      // }).catch(rek => {
      //   console.log(rek)
      // })
    },
    // 翻译大类
    findModelType(id) {
      let res = this.modelTypeOptions.find(v => v.id == id)
      return res ? res.model_type_name : id
    },
    // 翻译模型类型
    // findModelTypeDict(id) {
    //   let res = this.modelTypeDict.find(v => v.data_value == id)
    //   return res.data_label
    // },
    //打开新增弹窗
    handleAddDialog() {
      this.dialogVisible = true
      this.dialogTitle = "新增模型"
      this.modelListArr = [{ value: '' }]
      this.formData = {
        model_name: '',
        model_type: '',
        model_template_config_type_id: '',
        // model_conf_list: '',
      }
    },
    // 新增、修改确定按钮
    handleSubmit() {
      this.$refs.formData.validate((valid) => {
        if (valid) {
          // 处理自定义内容数据
          // this.formData.model_conf_list = JSON.stringify(this.modelListArr)
          let form = new FormData();

          // 遍历 msg 对象，并将键值对添加到 formData 中
          Object.keys(this.formData).forEach(key => {
            form.append(key, this.formData[key]);
          });
          const axiosUrl = this.dialogTitle === '新增模型' ? modelApi.addModel : modelApi.updateModel
          // 新增、修改
          this.$http.post(axiosUrl, form, this.config)
            .then(response => {
              if (response.data.code == 200) {
                this.$message({
                  type: 'success',
                  message: response.data.msg
                })
                this.dialogVisible = false
              } else {
                this.$message({
                  type: 'warning',
                  message: response.data.msg
                })
                this.dialogVisible = false
              }
              this.axioss()
            })
            .catch(rek => {
              console.log(rek)
            })
        }
      })
    },
    // 自定义内容加号+
    handleAddList() {
      this.modelListArr.push({ value: '' })
    },
    // 自定义内容减号-
    handleDeleteList(index) {
      this.modelListArr.splice(index, 1)
    },
    // 表格中修改按钮
    handleUpdateModel(row) {
      this.formData = row
      // if (row.model_conf_list != null) {
      //   this.modelListArr = JSON.parse(row.model_conf_list)
      // } else {
      //   this.modelListArr = [{ value: '' }]
      // }
      this.dialogTitle = '修改模型'
      this.dialogVisible = true
    },
    // 表格中删除按钮
    handleDeleteModel(row) {
      MessageBox.confirm('确定删除该模型吗？', '提示', {
        type: 'warning'
      }).then(() => {
        let data = {
          id: row.id
        }
        let form = new FormData()
        // 遍历 msg 对象，并将键值对添加到 formData 中
        Object.keys(data).forEach(key => {
          form.append(key, data[key]);
        });
        this.$http.post(modelApi.deleteModel, form, this.config)
          .then(response => {
            if (response.data.code == 200) {
              this.$message({
                type: 'success',
                message: response.data.msg
              })
            } else {
              this.$message({
                type: 'warning',
                message: response.data.msg
              })
            }
            this.axioss();
          })
          .catch(rek => {
            console.log(rek)
          })
      }).catch(() => {
        Message.info('已取消删除');
      });
    }
  }
};
  </script>
  
